/* Songs: notes [semitones from the key note, beats]; lyrics per language, one syllable per note, phrases separated by "/".
   Only traditional melodies and pre-1929 texts (public domain). */
const SONGS=[
 {id:"clair", name:"Au clair de la lune", bpm:92, notes:[
   [[0,1],[0,1],[0,1],[2,1],[4,2],[2,2],[0,1],[4,1],[2,1],[2,1],[0,4]],
   [[0,1],[0,1],[0,1],[2,1],[4,2],[2,2],[0,1],[4,1],[2,1],[2,1],[0,4]],
   [[2,1],[2,1],[2,1],[2,1],[-3,2],[-3,2],[2,1],[0,1],[-1,1],[-3,1],[-5,4]],
   [[0,1],[0,1],[0,1],[2,1],[4,2],[2,2],[0,1],[4,1],[2,1],[2,1],[0,4]]],
  lyr:{fr:"Au clair de la lu- ne, mon a- mi Pier- rot, / Prê- te- moi ta plu- me pour é- crire un mot. / Ma chan- delle est mor- te, je n'ai plus de feu. / Ou- vre- moi ta por- te pour l'a- mour de Dieu."}},
 {id:"ode", name:{de:"Ode an die Freude",en:"Joyful, joyful (Ode to Joy)",fr:"Ode à la joie"}, bpm:100, notes:[
   [[4,1],[4,1],[5,1],[7,1],[7,1],[5,1],[4,1],[2,1],[0,1],[0,1],[2,1],[4,1],[4,1.5],[2,.5],[2,2]],
   [[4,1],[4,1],[5,1],[7,1],[7,1],[5,1],[4,1],[2,1],[0,1],[0,1],[2,1],[4,1],[2,1.5],[0,.5],[0,2]]],
  lyr:{de:"Freu- de, schö- ner Göt- ter- fun- ken, Toch- ter aus E- ly- si- um, / wir be- tre- ten feu- er- trun- ken, Himm- li- sche, dein Hei- lig- tum!",
       en:"Joy- ful, joy- ful, we a- dore Thee, God of glo- ry, Lord of love; / Hearts un- fold like flowers be- fore Thee, O- pening to the sun a- bove."}},
 {id:"twinkle", name:"Twinkle, twinkle, little star", bpm:96, notes:[
   [[0,1],[0,1],[7,1],[7,1],[9,1],[9,1],[7,2]],[[5,1],[5,1],[4,1],[4,1],[2,1],[2,1],[0,2]],
   [[7,1],[7,1],[5,1],[5,1],[4,1],[4,1],[2,2]],[[7,1],[7,1],[5,1],[5,1],[4,1],[4,1],[2,2]],
   [[0,1],[0,1],[7,1],[7,1],[9,1],[9,1],[7,2]],[[5,1],[5,1],[4,1],[4,1],[2,1],[2,1],[0,2]]],
  lyr:{en:"Twin- kle, twin- kle, lit- tle star, / How I won- der what you are! / Up a- bove the world so high, / Like a dia- mond in the sky. / Twin- kle, twin- kle, lit- tle star, / How I won- der what you are!"}},
 {id:"jakob", name:{de:"Bruder Jakob",en:"Are you sleeping",fr:"Frère Jacques"}, bpm:100, notes:[
   [[0,1],[2,1],[4,1],[0,1],[0,1],[2,1],[4,1],[0,1]],[[4,1],[5,1],[7,2],[4,1],[5,1],[7,2]],
   [[7,.5],[9,.5],[7,.5],[5,.5],[4,1],[0,1],[7,.5],[9,.5],[7,.5],[5,.5],[4,1],[0,1]],[[0,1],[-5,1],[0,2],[0,1],[-5,1],[0,2]]],
  lyr:{de:ROUND_TXT.de,en:ROUND_TXT.en,fr:ROUND_TXT.fr}}];
// phrase markers for the round texts (same syllables as the canon)
(function(){ const s=SONGS[3].lyr, cut=(txt,ns)=>{ const w=txt.replace(/\s*\/\s*/g," ").split(/\s+/), out=[]; let k=0; ns.forEach(n=>{ out.push(w.slice(k,k+n).join(" ")); k+=n; }); return out.join(" / "); }, ns=SONGS[3].notes.map(p=>p.length); for(const l in s) s[l]=cut(s[l],ns); })();
const LV={b:{pitch:70,stab:35,time:250,sus:70,dyn:8},i:{pitch:85,stab:25,time:160,sus:80,dyn:6},a:{pitch:95,stab:15,time:110,sus:90,dyn:4}};
const LANG_NAME={en:{en:"English",de:"German",fr:"French"},de:{en:"Englisch",de:"Deutsch",fr:"Französisch"},fr:{en:"anglais",de:"allemand",fr:"français"}};
const allSongs=()=>SONGS.concat(store.mySongs||[]);
let SG={id:null,lv:"i",guide:true,gm:null,bpm:null,phrase:null,phStreak:0,last:null};
const songName=s=>typeof s.name==="string"?s.name:(s.name[SET.ui]||s.name.en);
function songLang(s){ return s.lyr[SET.tl]?SET.tl:(Object.keys(s.lyr)[0]||SET.tl); }
function sgStore(id){ store.choirSongs=store.choirSongs||{}; return store.choirSongs[id]=store.choirSongs[id]||{runs:0,best:0,mastered:{}}; }
/* build timed targets for the whole song or a single phrase */
function songTargets(s,shift,beat,phrase){
  const l=songLang(s), syl=s.lyr[l]?s.lyr[l].split("/").map(p=>p.trim().split(/\s+/)):[]; let tt=0; const out=[];
  s.notes.forEach((ph,pi)=>{ if(phrase!=null&&pi!==phrase) return; const sung=ph.filter(n=>n[0]!=null), lastI=ph.lastIndexOf(sung[sung.length-1]); let si=0; ph.forEach(([st,b],ni)=>{ if(st==null){ if(!(phrase!=null&&ni===0)) tt+=b*beat; return; } out.push({m:60+st+shift,t:tt,d:b*beat,label:(syl[pi]&&syl[pi][si])||(s.my?nName(60+st+shift):""),ph:pi,last:ni===lastI,beats:b}); si++; tt+=b*beat; }); });
  if(out.length&&out[0].t>0){ const o=out[0].t; out.forEach(n=>n.t-=o); tt-=o; }
  return {targets:out,dur:tt};
}
function songShift(s){ const [lo,hi]=vRange(), all=s.notes.flat().map(n=>n[0]).filter(x=>x!=null), mn=Math.min(...all), mx=Math.max(...all);
  if(s.my){ let b=0,bs=1e9; [-24,-12,0,12,24].forEach(k=>{ const sc=Math.max(0,lo-(60+mn+k))+Math.max(0,60+mx+k-hi); if(sc<bs){ bs=sc; b=k; } }); return b; }
  let best=0,bs=1e9; for(let k=-30;k<=12;k++){ const a=60+mn+k, b=60+mx+k, over=Math.max(0,lo+1-a)+Math.max(0,b-(hi-1)), sc=over*20+Math.abs((a+b)/2-(lo+hi)/2); if(sc<bs){ bs=sc; best=k; } }
  while(!KEYPC.includes((((60+best)%12)+12)%12)) best--; return best; }
/* five parameters from the per-note results */
function songMetrics(res){
  const voiced=res.filter(n=>!n.miss), pitch=Math.round(100*res.filter(n=>n.ok).length/Math.max(1,res.length));
  const sds=voiced.filter(n=>n.d>=0.4&&!n.oct&&Math.abs(n.cents)<80).map(n=>n.sd), stab=sds.length?Math.round(pctl(sds,0.5)):null;
  const ch=res.filter((n,i)=>i>0&&n.m!==res[i-1].m&&n.ph===res[i-1].ph), lats=ch.map(n=>n.lat==null?n.d:Math.abs(n.lat)), time=lats.length?Math.round(1000*pctl(lats,0.5)):null;
  const longs=res.filter(n=>n.beats>=2||n.last), sus=longs.length?Math.round(100*longs.reduce((a,n)=>a+(n.miss?0:n.sus),0)/longs.length):null;
  const phs=[...new Set(res.map(n=>n.ph))], drops=phs.map(p=>{ const ns=res.filter(n=>n.ph===p&&n.dbm!=null); const lastN=res.filter(n=>n.ph===p&&n.last)[0]; if(!lastN||lastN.dbe==null||ns.length<3) return null; return pctl(ns.map(n=>n.dbm),0.5)-lastN.dbe; }).filter(x=>x!=null), dyn=drops.length?Math.max(0,Math.round(10*drops.reduce((a,b)=>a+b,0)/drops.length)/10):null;
  const perPh=phs.map(p=>{ const ns=res.filter(n=>n.ph===p); return {p,acc:Math.round(100*ns.filter(n=>n.ok).length/ns.length)}; });
  return {pitch,stab,time,sus,dyn,perPh};
}
function metOk(k,v,L){ if(v==null) return false; return (k==="pitch"||k==="sus")?v>=L[k]:v<=L[k]; }
function renderSongs(){
  const box=$("#sgBody"); if(!box) return;
  const ALL=allSongs(); if(!SG.id||!ALL.find(x=>x.id===SG.id)){ const own=SONGS.find(s=>s.lyr[SET.tl]); SG.id=(own||SONGS[0]).id; }
  const s=ALL.find(x=>x.id===SG.id), l=songLang(s), st=sgStore(s.id), shift=songShift(s), bpm=SG.bpm||s.bpm;
  box.innerHTML=`<p class="muted">${t("sg_desc")}</p>
   <div class="row"><span class="muted">${t("sg_song")}:</span></div><div class="chips" data-s></div>
   <div class="row"><span class="muted">${t("sg_level")}:</span><div class="chips" data-l></div></div>
   <div class="row"><span class="muted">${t("pt_slow")}:</span><div class="chips" data-t></div><span class="muted">${t("sg_guide")}:</span><div class="chips" data-g></div></div>
   <p class="muted" style="font-size:.8rem">${s.my&&s.audio===undefined?`<span class="warnbox" style="display:block;margin-bottom:4px">${t("my_old")}</span>`:""}${s.my?"🎙 "+t("my_tag"):t("sg_lyr",{l:LANG_NAME[SET.ui][l]})+(s.lyr[SET.tl]?"":" "+t("sg_orig"))} · ${t("nt_key",{n:nName(60+shift)})} · ${t("sg_hist",{n:st.runs})}${st.best?" · "+t("sg_best",{p:st.best}):""}${Object.keys(st.mastered).length?" · "+t("sg_mastered",{l:Object.keys(st.mastered).map(k=>t("lv_"+k)).join(", ")}):""}</p>
   <div class="card flat" data-lyr ${tlAttr(l)} style="line-height:1.9;font-size:1.02rem"></div>
   ${SG.phrase!=null?`<div class="warnbox">${t("sg_phrase_mode",{n:SG.phrase+1,a:SG.phStreak})}</div>`:""}
   <div data-lane></div>
   ${s.my?`<div class="row"><button class="b alt sm grow" data-syn>${t("my_hear_notes")}</button>${s.audio?`<button class="b alt sm grow" data-fix>${t("my_fix")}</button>`:""}</div>`:""}
   <div class="row"><button class="b alt grow" data-lis>${t("sg_listen")}</button><button class="b warm grow" data-go>${SG.phrase!=null?t("sg_phrase_go",{n:SG.phrase+1}):t("sg_go")}</button></div>
   ${SG.phrase!=null?`<button class="b alt sm" data-back style="margin-top:6px">${t("sg_back")}</button>`:""}<div data-out></div>${s.my?`<button class="b alt sm" data-del style="margin-top:8px">🗑 ${t("my_del")}</button>`:""}`;
  if(s.my) box.querySelector("[data-del]").onclick=()=>{ SongAudio.del(s.id); store.mySongs=(store.mySongs||[]).filter(x=>x.id!==s.id); save(); SG.id=null; SG.last=null; renderSongs(); };
  renderMySong(box);
  chipSet(box.querySelector("[data-s]"),ALL.slice().sort((a,b)=>(!!b.lyr[SET.tl]-!!a.lyr[SET.tl])||(!!a.my-!!b.my)).map(x=>[x.id,(x.my?"🎙 ":"")+songName(x)+(sgStore(x.id).mastered[SG.lv]?" ✓":"")]),s.id,v=>{ SG.id=v; SG.bpm=null; SG.phrase=null; SG.last=null; renderSongs(); });
  chipSet(box.querySelector("[data-l]"),["b","i","a"].map(k=>[k,t("lv_"+k)]),SG.lv,v=>{ SG.lv=v; renderSongs(); });
  chipSet(box.querySelector("[data-t]"),[Math.round(s.bpm*0.75),s.bpm,Math.round(s.bpm*1.15)].map(v=>[v,s.my?Math.round(v/s.bpm*100)+" "+t("my_pct"):String(v)]),bpm,v=>{ SG.bpm=+v; renderSongs(); });
  const gms=s.my&&s.audio?[["orig",t("my_orig")],["synth",t("my_synth")],["off",t("sg_off")]]:[["synth",t("sg_on")],["off",t("sg_off")]];
  if(!SG.gm||!gms.find(g=>g[0]===SG.gm)) SG.gm=s.my&&s.audio?"orig":(SG.guide?"synth":"off");
  chipSet(box.querySelector("[data-g]"),gms,SG.gm,v=>{ SG.gm=v; SG.guide=v!=="off"; renderSongs(); });
  const useOrig=SG.gm==="orig", rate=bpm/s.bpm;
  const beat=60/bpm, {targets,dur}=songTargets(s,shift,beat,SG.phrase);
  // lyrics with one span per syllable
  const ly=box.querySelector("[data-lyr]"); let lines={}; targets.forEach((n,i)=>{ (lines[n.ph]=lines[n.ph]||[]).push(`<span data-i="${i}" style="padding:1px 2px;border-radius:4px">${esc(n.label)}</span>`); });
  ly.innerHTML=Object.keys(lines).map(p=>`<div><span class="muted" style="font-size:.75rem">${+p+1}</span> ${lines[p].join(" ").replace(/-<\/span> /g,"-</span>")}</div>`).join("");
  const mid=Math.round((Math.min(...targets.map(n=>n.m))+Math.max(...targets.map(n=>n.m)))/2), lane=laneView(box.querySelector("[data-lane]"),targets,mid);
  const hl=i=>{ ly.querySelectorAll("span[data-i]").forEach(e=>{ const k=+e.dataset.i; e.style.background=k===i?"var(--accent2)":""; e.style.color=k===i?"#fff":(k<i?"var(--muted)":""); }); };
  if(SG.last&&SG.last.id===s.id&&SG.last.phrase===SG.phrase) showSongResult(box,s,SG.last.res,SG.last.m);
  const origOff=()=>s.phT?s.phT[SG.phrase==null?0:SG.phrase]:0;
  const hasOrig=s.my&&s.audio;
  const prevStart=(btn,len)=>{ const c=ac(); stopGuide(); GUIDE.out=c.createGain(); GUIDE.out.connect(c.destination); AOUT=GUIDE.out; btn.dataset.lbl=btn.innerHTML; btn.innerHTML="■ "+t("sess_stop"); GUIDE.timers.push(setTimeout(stopGuide,(len+0.8)*1000)); };
  box.querySelector("[data-lis]").onclick=async e=>{ const btn=e.currentTarget; if(btn.dataset.lbl){ stopGuide(); return; } prevStart(btn,dur); const c=ac(), t0=c.currentTime+0.25;
    if(hasOrig){ await playOrig(s,origOff(),dur+0.3,rate,0.25); } else targets.forEach(n=>synthVoice(c,n.m,t0+n.t,n.d*0.95,0.16));
    targets.forEach((n,i)=>GUIDE.timers.push(setTimeout(()=>hl(i),(0.25+n.t)*1000))); GUIDE.timers.push(setTimeout(()=>hl(-1),(0.4+dur)*1000)); };
  if(box.querySelector("[data-syn]")) box.querySelector("[data-syn]").onclick=e=>{ const btn=e.currentTarget; if(btn.dataset.lbl){ stopGuide(); return; } prevStart(btn,dur); const c=ac(), t0=c.currentTime+0.25; targets.forEach((n,i)=>{ synthVoice(c,n.m,t0+n.t,n.d*0.95,0.16); GUIDE.timers.push(setTimeout(()=>hl(i),(0.25+n.t)*1000)); }); GUIDE.timers.push(setTimeout(()=>hl(-1),(0.4+dur)*1000)); };
  if(box.querySelector("[data-fix]")) box.querySelector("[data-fix]").onclick=()=>singAlongFix(box,s);
  if(box.querySelector("[data-back]")) box.querySelector("[data-back]").onclick=()=>{ SG.phrase=null; SG.phStreak=0; SG.last=null; renderSongs(); };
  box.querySelector("[data-go]").onclick=async()=>{ const go=box.querySelector("[data-go]"); go.disabled=true; lane.reset();
    stopGuide(); const orig=useOrig&&hasOrig, buf=orig&&rate===1?await SongAudio.get(s.id):null;
    const acc=buf?[{buf,t:0,off:origOff(),d:dur+0.2,v:0.8}]:(!orig&&SG.gm!=="off"?targets.map(n=>({m:n.m,t:n.t,d:n.d*0.95,v:0.08,voice:1})):[]);
    const cues=orig&&!buf?[{t:-0.05,fn:()=>playOrig(s,origOff(),dur+0.2,rate,0)}]:[];
    // light chord support on the key note at each phrase start, also without the guide melody
    if(!s.my) [...new Set(targets.map(n=>n.ph))].forEach(p=>{ const f=targets.find(n=>n.ph===p); acc.push({m:60+shift-12,t:f.t,d:Math.min(2,beat*2),v:0.05,organ:true}); });
    const out=await singSession({acc,targets,countIn:4,beat,total:dur,cues,onLive:(f,rel)=>{ if(rel>=-0.2) lane.pushAt(f,rel); },onPhase:i=>hl(i)});
    go.disabled=false; hl(-1); if(!out) return;
    const m=songMetrics(out.res); st.runs++; if(SG.phrase==null) st.best=Math.max(st.best,m.pitch);
    const L=LV[SG.lv], met=["pitch","stab","time","sus","dyn"].filter(k=>metOk(k,m[k],L));
    if(SG.phrase==null&&met.length===5) st.mastered[SG.lv]=today();
    if(SG.phrase!=null){ SG.phStreak=m.pitch>=L.pitch?SG.phStreak+1:0; }
    save(); SG.last={id:s.id,phrase:SG.phrase,res:out.res,m};
    logSession(songName(s),Math.max(0.5,dur/60));
    if(SG.phrase!=null&&SG.phStreak>=2){ const n=SG.phrase+1; SG.phrase=null; SG.phStreak=0; SG.last=null; renderSongs(); $("#sgBody [data-out]").innerHTML=`<div class="okbox" style="margin-top:8px">${t("sg_phrase_done",{n})}</div>`; return; }
    renderSongs(); };
}
function showSongResult(box,s,res,m){
  const L=LV[SG.lv], keys=["pitch","stab","time","sus","dyn"], unit={pitch:" %",stab:" ct",time:" ms",sus:" %",dyn:" dB"}, cmp={pitch:"≥",sus:"≥",stab:"≤",time:"≤",dyn:"≤"};
  const ok=keys.filter(k=>metOk(k,m[k],L)), worst=m.perPh.slice().sort((a,b)=>a.acc-b.acc)[0];
  const rows=keys.map(k=>`<tr><td>${metOk(k,m[k],L)?"✅":"⬜"} <b>${t("pm_"+k)}</b><br><span class="muted" style="font-size:.75rem">${t("pm_"+k+"_u")}</span></td><td style="text-align:right">${m[k]==null?"–":m[k]+unit[k]}</td><td style="text-align:right">${cmp[k]} ${L[k]}${unit[k]}</td></tr>`).join("");
  const o=box.querySelector("[data-out]"), all=ok.length===5&&SG.phrase==null;
  o.innerHTML=`<div class="${all?"okbox":"warnbox"}" style="margin-top:8px">
     <table style="width:100%;border-collapse:collapse;font-size:.85rem"><tr class="muted"><td>${t("sg_col_p")}</td><td style="text-align:right">${t("sg_col_v")}</td><td style="text-align:right">${t("sg_col_t")}</td></tr>${rows}</table>
     ${m.perPh.length>1?`<p style="margin:6px 0 2px"><b>${t("sg_ph")}</b> ${m.perPh.map(p=>`<span class="kp ${p.acc>=L.pitch?"hit":"miss"}">${p.p+1}: ${p.acc} %</span>`).join("")}</p>`:""}
     ${resultList(res)}
     ${all?`<p><b>${t("sg_all",{l:t("lv_"+SG.lv)})}</b></p>`:ok.length<5?`<p><b>${t("sg_some",{c:ok.length})}</b></p><ul class="list" data-nx></ul>`:""}</div><div class="row" data-btn style="margin-top:6px"></div>`;
  const nx=o.querySelector("[data-nx]"), btns=o.querySelector("[data-btn]"), add=(txt,fn,warm)=>{ const b=el("button",{class:"b sm "+(warm?"warm":"alt")},txt); b.onclick=fn; btns.append(b); };
  const again=el("button",{class:"b sm"},t("nt_again")); again.onclick=()=>box.querySelector("[data-go]").click(); btns.append(again);
  if(!nx) return; const li=x=>nx.insertAdjacentHTML("beforeend",`<li>${esc(x)}</li>`);
  if(!metOk("pitch",m.pitch,L)){
    if(SG.phrase==null&&m.perPh.length>1){ li(t("nx_pitch",{n:worst.p+1})); add(t("sg_go_ph",{n:worst.p+1}),()=>{ SG.phrase=worst.p; SG.phStreak=0; SG.last=null; renderSongs(); scrollToId("sgCard"); },true); }
    const wrong=[...new Set(res.filter(n=>!n.ok).map(n=>n.m))]; if(wrong.length){ add(t("nx_wrong",{n:wrong.length}),()=>{ NT.only=wrong; NT.round=0; scrollToId("ntCard"); runNotes($("#ntBody")); }); }
    tendencyTips(res).forEach(li);
  }
  if(!metOk("stab",m.stab,L)){ li(t("nx_stab")); add(t("sg_go_long"),()=>{ NT.ex="long"; NT.only=null; NT.round=0; renderNotes(); scrollToId("ntCard"); }); }
  if(!metOk("time",m.time,L)){ const slow=Math.round(s.bpm*0.75); li(t("nx_time",{b:s.my?"75 "+t("my_pct"):slow})); add(t("sg_go_slow"),()=>{ SG.bpm=slow; SG.last=null; renderSongs(); }); }
  if(!metOk("sus",m.sus,L)) li(t("nx_sus"));
  if(!metOk("dyn",m.dyn,L)) li(t("nx_dyn"));
  if(!metOk("sus",m.sus,L)||!metOk("dyn",m.dyn,L)) add(t("sg_go_breath"),()=>{ show("breath"); scrollToId("supCard"); });
}

